def solve(input_data):
    graph = input_data['graph']
    indegree = {n: 0 for n in graph}
    for u, neighbors in graph.items():
        for v in neighbors:
            indegree[v] += 1
    from collections import deque
    q = deque([n for n in graph if indegree[n] == 0])
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)
    return order

