def solve(input_data):
    graph = input_data['graph']
    visited = set()
    order = []
    def dfs(u):
        visited.add(u)
        for v in sorted(graph[u], reverse=True):
            if v not in visited:
                dfs(v)
        order.append(u)
    for node in graph:
        if node not in visited:
            dfs(node)
    order.reverse()
    return order

